fn golden() -> Value {
    serde_json::from_str(include_str!("golden/task33-selectors.json")).expect("golden parses")
}

/// The manager the selector components see in the app: TUI ids plus the app.* ids from maho-core.
fn full_keybindings() -> Arc<KeybindingsManager> {
    Arc::new(KeybindingsManager::new(
        maho_core::keybindings::keybindings().clone(),
        maho_tui::keybindings::KeybindingsConfig::default(),
    ))
}

fn theme() -> Theme {
    Theme::builtin("dark", ColorMode::Truecolor).expect("builtin dark theme")
}

fn models_from_golden(value: &Value) -> Vec<ModelEntry> {
    value["models"]
        .as_array()
        .expect("models array")
        .iter()
        .map(|model| ModelEntry {
            provider: model["provider"].as_str().unwrap_or_default().to_owned(),
            id: model["id"].as_str().unwrap_or_default().to_owned(),
            name: model["name"].as_str().unwrap_or_default().to_owned(),
        })
        .collect()
}

fn sessions_from_golden(value: &Value) -> Vec<SessionInfo> {
    value["sessions"]
        .as_array()
        .expect("sessions array")
        .iter()
        .map(|session| SessionInfo {
            path: session["path"].as_str().unwrap_or_default().to_owned(),
            id: session["id"].as_str().unwrap_or_default().to_owned(),
            cwd: session["cwd"].as_str().unwrap_or_default().to_owned(),
            name: session["name"].as_str().map(str::to_owned),
            parent_session_path: None,
            modified_ms: session["modifiedMs"].as_i64().unwrap_or_default(),
            message_count: session["messageCount"].as_u64().unwrap_or_default() as usize,
            first_message: session["firstMessage"].as_str().unwrap_or_default().to_owned(),
            all_messages_text: session["allMessagesText"].as_str().unwrap_or_default().to_owned(),
        })
        .collect()
}

fn expected_ids(entry: &Value) -> Vec<String> {
    entry
        .as_array()
        .expect("expected rows")
        .iter()
        .map(|id| id.as_str().unwrap_or_default().to_owned())
        .collect()
}

/// The model selector's filtered rows equal the pinned senpi ranking for every golden query.
#[test]
fn model_selector_rows_match_pinned_senpi_ranking() {
    let golden = golden();
    let models = models_from_golden(&golden);
    let favorites: Vec<String> = golden["favoriteIds"]
        .as_array()
        .expect("favoriteIds")
        .iter()
        .map(|id| id.as_str().unwrap_or_default().to_owned())
        .collect();
    let theme = theme();
    let keybindings = full_keybindings();

    for case in golden["modelSelector"].as_array().expect("modelSelector") {
        let query = case["query"].as_str().unwrap_or_default();
        if query.is_empty() {
            // An empty query shows the component's own sort (current, favorites, provider/id);
            // the ranking function's empty-query order is covered by task33_search.rs.
            continue;
        }
        let expected = expected_ids(&case["rows"]);
        let selector = ModelSelectorComponent::new(
            &theme,
            keybindings.clone(),
            1,
            &models,
            None,
            Vec::new(),
            Box::new(|_| {}),
            Box::new(|| {}),
            Some(query),
            ModelSelectorFavoriteOptions {
                favorite_model_ids: Some(favorites.clone()),
                on_favorite_change: None,
            },
            None,
        );
        assert_eq!(selector.filtered_model_ids(), expected, "query {query:?}");
        // A non-empty query highlights the first row, an empty one keeps the opening position.
        if !query.is_empty() {
            assert_eq!(selector.selected_index(), 0, "query {query:?}");
        }
    }
}

