/// Every pinned session-search case keeps senpi's order for all three sort modes.
#[test]
fn session_search_matches_pinned_senpi() {
    let golden = golden();
    let sessions = sessions_from_golden(&golden);
    for case in golden["sessionSearch"].as_array().expect("sessionSearch") {
        let query = case["query"].as_str().unwrap_or_default();
        let parsed = parse_search_query(query);
        assert_eq!(
            parsed.error.is_some(),
            !case["parsedError"].is_null(),
            "error presence for {query:?}"
        );
        for (key, mode) in [("recent", SortMode::Recent), ("relevance", SortMode::Relevance)] {
            let ids: Vec<String> = filter_and_sort_sessions(&sessions, query, mode, NameFilter::All)
                .into_iter()
                .map(|session| session.id)
                .collect();
            assert_eq!(ids, expected_ids(&case[key]), "{key} for {query:?}");
        }
        let named: Vec<String> = filter_and_sort_sessions(&sessions, query, SortMode::Recent, NameFilter::Named)
            .into_iter()
            .map(|session| session.id)
            .collect();
        assert_eq!(named, expected_ids(&case["named"]), "named for {query:?}");
    }
}

/// A session counts as named only when the trimmed name is non-empty.
#[test]
fn session_name_detection_matches_senpi() {
    let golden = golden();
    let sessions = sessions_from_golden(&golden);
    for case in golden["helpers"]["hasSessionName"].as_array().expect("hasSessionName") {
        let id = case[0].as_str().unwrap_or_default();
        let expected = case[1].as_bool().unwrap_or_default();
        let mut session = sessions.iter().find(|session| session.id == id).cloned().expect("session");
        if case[0].as_str() == Some("s1") && !expected {
            session.name = Some("   ".to_owned());
        }
        assert_eq!(has_session_name(&session), expected, "{id}");
    }
}

/// Phrase tokens, regex mode and a broken regex behave like senpi's parser.
#[test]
fn session_search_parser_modes_match_senpi() {
    let sessions = sessions_from_golden(&golden());
    let phrase = parse_search_query("\"node cve\"");
    assert_eq!(phrase.tokens.len(), 1);
    assert!(match_session(&sessions[0], &phrase).matches);
    assert!(!match_session(&sessions[1], &phrase).matches);

    let regex = parse_search_query("re:beta");
    assert!(regex.regex.is_some());
    assert_eq!(
        filter_and_sort_sessions(&sessions, "re:beta", SortMode::Recent, NameFilter::All)
            .into_iter()
            .map(|session| session.id)
            .collect::<Vec<_>>(),
        vec!["s3".to_owned()]
    );

    let broken = parse_search_query("re:[");
    assert!(broken.error.is_some());
    assert!(filter_and_sort_sessions(&sessions, "re:[", SortMode::Recent, NameFilter::All).is_empty());
}

/// The favorite-model id helpers match the pinned senpi results.
#[test]
fn favorite_model_helpers_match_pinned_senpi() {
    let golden = golden();
    let expected = &golden["favorites"];
    let all_ids: Vec<String> = models_from_golden(&golden)
        .iter()
        .map(ModelEntry::full_id)
        .collect();
    let favorite_ids = vec!["openai/gpt-5.2".to_owned()];

    assert_eq!(
        toggle_favorite_model(&None, &all_ids, "openai/gpt-5.2"),
        Some(expected_ids(&expected["toggleFromAll"]))
    );
    assert_eq!(
        toggle_favorite_model(&Some(favorite_ids.clone()), &all_ids, "openai/gpt-5.2"),
        Some(expected_ids(&expected["toggleOff"]))
    );
    assert_eq!(
        toggle_favorite_model(&Some(Vec::new()), &all_ids, "zai/glm-5.2"),
        Some(expected_ids(&expected["toggleOn"]))
    );
    assert_eq!(favorite_models(&Some(Vec::new()), &all_ids, None), None);
    assert_eq!(
        clear_favorite_models(&Some(favorite_ids.clone()), &all_ids, Some(&["openai/gpt-5.2".to_owned()])),
        Some(expected_ids(&expected["clearFiltered"]))
    );
    assert_eq!(
        clear_favorite_models(&None, &all_ids, None),
        Some(expected_ids(&expected["clearAll"]))
    );
    assert_eq!(
        move_favorite_model(&Some(vec!["a".to_owned(), "b".to_owned(), "c".to_owned()]), "b", -1),
        Some(expected_ids(&expected["moveUp"]))
    );
    assert_eq!(
        get_sorted_favorite_model_ids(&Some(vec!["zai/glm-5.2".to_owned()]), &all_ids),
        expected_ids(&expected["sorted"])
    );
}

/// The favorite-models selector keeps the frozen display order and toggles membership.
#[test]
fn favorite_models_selector_keeps_frozen_row_order() {
    let golden = golden();
    let models = models_from_golden(&golden);
    let theme = theme();
    let selected = Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
    let changed = Rc::clone(&selected);
    let persisted = Rc::clone(&selected);
    let mut component = FavoriteModelsSelectorComponent::new(
        &theme,
        full_keybindings(),
        FavoriteModelsConfig {
            all_models: models.clone(),
            favorite_model_ids: Some(vec!["openai/gpt-5.2".to_owned()]),
            current_model: Some(models[2].clone()),
        },
        FavoriteModelsCallbacks {
            on_change: Box::new(move |ids| *changed.borrow_mut() = ids.unwrap_or_default()),
            on_persist: Box::new(move |ids| *persisted.borrow_mut() = ids.unwrap_or_default()),
            on_select: Box::new(|_| {}),
            on_cancel: Box::new(|| {}),
        },
    );
    let initial = component.filtered_ids();
    assert_eq!(initial.first().map(String::as_str), Some("openai/gpt-5.2"));
    assert!(!component.is_dirty());

    // Ctrl+F toggles the selected row's membership and marks the surface dirty.
    component.handle_input("\u{6}");
    assert!(component.is_dirty());
    assert_eq!(component.favorite_ids(), &Some(Vec::new()));
    assert_eq!(component.filtered_ids(), initial, "row order stays frozen");

    component.handle_input("\u{13}");
    assert_eq!(*selected.borrow(), Vec::<String>::new());
}

/// A three-branch session renders senpi's tree glyphs and keeps the active path marked.
#[test]
fn tree_selector_renders_senpi_branch_glyphs() {
    let theme = theme();
    let tree = three_branch_tree();
    let mut selector = TreeSelectorComponent::new(
        &theme,
        full_keybindings(),
        tree,
        Some("leaf-b"),
        24,
        Box::new(|_| {}),
        Box::new(|| {}),
        None,
        None,
        None,
        None,
    );
    let rendered = selector.render(80).join("\n");
    assert!(rendered.contains("Session Tree"), "{rendered}");
    assert!(rendered.contains("├─ ") || rendered.contains("└─ "), "{rendered}");
    assert!(rendered.contains("│"), "{rendered}");
    assert!(rendered.contains("• "), "{rendered}");
    assert!(rendered.contains("assistant: "), "{rendered}");
    assert!(rendered.contains("user: "), "{rendered}");

    let tree_list = selector.tree_list();
    let ids = tree_list.borrow().filtered_entry_ids();
    assert!(ids.contains(&"leaf-b".to_owned()));
    assert_eq!(tree_list.borrow().filter_mode(), FilterMode::Default);
}

/// The tree list's filter modes change which entries are visible.
#[test]
fn tree_selector_filter_modes_narrow_entries() {
    let theme = theme();
    let selector = TreeSelectorComponent::new(
        &theme,
        full_keybindings(),
        three_branch_tree(),
        Some("leaf-b"),
        24,
        Box::new(|_| {}),
        Box::new(|| {}),
        None,
        None,
        None,
        None,
    );
    let all = selector.tree_list().borrow().filtered_entry_ids();
    assert_eq!(all.len(), 5);

    // app.tree.filter.userOnly is ctrl+u in the default keybindings.
    selector.tree_list().borrow_mut().handle_input("\u{15}");
    let user_only = selector.tree_list().borrow().filtered_entry_ids();
    assert_eq!(user_only, vec!["root".to_owned(), "branch-c".to_owned()]);
    assert_eq!(selector.tree_list().borrow().filter_mode(), FilterMode::UserOnly);

    // ctrl+d returns to the default view.
    selector.tree_list().borrow_mut().handle_input("\u{4}");
    assert_eq!(selector.tree_list().borrow().filtered_entry_ids(), all);
}

/// The session selector builds senpi's parent/child tree and flattens it with tree metadata.
#[test]
fn session_selector_builds_and_flattens_the_session_tree() {
    let sessions = vec![
        session("root", "/s/root.jsonl", None, 3_000),
        session("child", "/s/child.jsonl", Some("/s/root.jsonl"), 2_000),
        session("grandchild", "/s/grandchild.jsonl", Some("/s/child.jsonl"), 1_000),
        session("sibling", "/s/sibling.jsonl", Some("/s/root.jsonl"), 500),
    ];
    let roots = build_session_tree(&sessions);
    assert_eq!(roots.len(), 1);
    assert_eq!(roots[0].session.id, "root");
    assert_eq!(roots[0].children.len(), 2);
    // Sorted by latest subtree activity: child (grandchild at 1000) before sibling (500).
    assert_eq!(roots[0].children[0].session.id, "child");
    assert_eq!(roots[0].children[1].session.id, "sibling");
    assert_eq!(roots[0].latest_activity, 3_000);

    let flat = flatten_session_tree(&roots);
    let shapes: Vec<(String, usize, String)> = flat
        .iter()
        .map(|node| (node.session.id.clone(), node.depth, build_tree_prefix(node)))
        .collect();
    assert_eq!(
        shapes,
        vec![
            ("root".to_owned(), 0, String::new()),
            ("child".to_owned(), 1, "   ├─ ".to_owned()),
            ("grandchild".to_owned(), 2, "   │  └─ ".to_owned()),
            ("sibling".to_owned(), 1, "   └─ ".to_owned()),
        ]
    );
}

