/// The session selector header shows the scope, sort and name-filter state.
#[test]
fn session_selector_header_and_scope_toggle() {
    let theme = theme();
    let loaded = Rc::new(std::cell::Cell::new(0));
    let loader_counter = Rc::clone(&loaded);
    let all_sessions = vec![session("a", "/s/a.jsonl", None, 1_000)];
    let mut component = SessionSelectorComponent::new(
        &theme,
        full_keybindings(),
        Box::new(move |_| {
            loader_counter.set(loader_counter.get() + 1);
            vec![session("a", "/s/a.jsonl", None, 1_000)]
        }),
        Box::new(move |_| all_sessions.clone()),
        Box::new(|_| {}),
        Box::new(|| {}),
        Box::new(|| {}),
        Box::new(|| {}),
        None,
        None,
        Some("/s/a.jsonl"),
        None,
    );
    assert_eq!(loaded.get(), 1, "the current-folder loader ran once on construction");
    assert_eq!(component.scope(), SessionScope::Current);
    let current = component.render(120).join("\n");
    assert!(current.contains("Resume Session (Current Folder)"), "{current}");
    assert!(current.contains("◉ Current Folder"), "{current}");

    component.toggle_scope();
    assert_eq!(component.scope(), SessionScope::All);
    let all = component.render(120).join("\n");
    assert!(all.contains("Resume Session (All)"), "{all}");
    assert!(all.contains("◉ All"), "{all}");

    component.toggle_sort_mode();
    assert_eq!(component.sort_mode(), SortMode::Recent);
    assert!(component.render(120).join("\n").contains("Sort: "));
    component.toggle_name_filter();
    let named = component.render(120).join("\n");
    assert!(named.contains("Name: "), "{named}");
    assert!(named.contains("Named"), "{named}");
}

/// The session selector's rename mode swaps the list for a labelled input.
#[test]
fn session_selector_rename_mode_round_trip() {
    let theme = theme();
    let renamed = Rc::new(std::cell::RefCell::new(Vec::<(String, String)>::new()));
    let sink = Rc::clone(&renamed);
    let mut component = SessionSelectorComponent::new(
        &theme,
        full_keybindings(),
        Box::new(|_| Vec::new()),
        Box::new(|_| Vec::new()),
        Box::new(|_| {}),
        Box::new(|| {}),
        Box::new(|| {}),
        Box::new(|| {}),
        Some(Box::new(move |path, name| {
            sink.borrow_mut().push((path.to_owned(), name.unwrap_or_default().to_owned()));
        })),
        None,
        None,
        None,
    );
    assert!(component.can_rename());
    component.enter_rename_mode("/s/a.jsonl", Some("old"));
    assert!(component.render(80).join("\n").contains("Rename Session"));
    component.rename_input_mut().set_value("new name");
    let value = component.rename_input().get_value().to_owned();
    component.confirm_rename(&value);
    assert_eq!(*renamed.borrow(), vec![("/s/a.jsonl".to_owned(), "new name".to_owned())]);
    assert!(component.render(80).join("\n").contains("Resume Session"));
}

/// The settings selector lists every setting id senpi ships, in senpi's order.
#[test]
fn settings_selector_lists_senpi_settings_in_order() {
    let theme = theme();
    let config = SettingsConfig {
        available_themes: vec!["dark".to_owned(), "light".to_owned()],
        ..SettingsConfig::default()
    };
    let mut selector = SettingsSelectorComponent::new(&theme, config, Default::default(), false);

    // The window is ten rows and follows the selection; select the first id senpi ships.
    selector.settings_list_mut().select_item("autocompact");
    let head = selector.render(200).join("\n");
    assert!(head.contains("Auto-compact"), "{head}");
    assert!(head.contains("Block images"), "{head}");

    // The last id senpi ships is the theme submenu.
    selector.settings_list_mut().select_item("theme");
    let tail = selector.render(200).join("\n");
    assert!(tail.contains("Theme"), "{tail}");
}

/// The settings selector reports changes for the settings it can change without a submenu.
#[test]
fn settings_selector_dispatches_scalar_changes() {
    let theme = theme();
    let seen = Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
    let sink = Rc::clone(&seen);
    let callbacks = maho_interactive::components::settings_selector::SettingsCallbacks {
        on_auto_compact_change: Some(Box::new({
            let sink = Rc::clone(&sink);
            move |value| sink.borrow_mut().push(format!("autocompact={value}"))
        })),
        on_tui_mode_change: Some(Box::new({
            let sink = Rc::clone(&sink);
            move |mode| sink.borrow_mut().push(format!("tui={}", mode.as_str()))
        })),
        ..Default::default()
    };
    let mut selector = SettingsSelectorComponent::new(&theme, SettingsConfig::default(), callbacks, true);
    let rendered = selector.render(200).join("\n");
    assert!(rendered.contains("Show images"), "{rendered}");
    assert!(rendered.contains("Image width"), "{rendered}");
    assert!(seen.borrow().is_empty(), "no change before a key is sent");

    // Enter on the first row (Auto-compact) cycles the value and reports it.
    selector.handle_input("\r");
    assert_eq!(seen.borrow().len(), 1, "{:?}", seen.borrow());
    assert!(seen.borrow()[0].starts_with("autocompact="), "{:?}", seen.borrow());
}

/// The config selector groups resources by origin/scope and toggles a top-level resource.
#[test]
fn config_selector_groups_resources_and_toggles_them() {
    use maho_core::package_manager::{PathMetadata, ResolvedPaths, ResolvedResource};
    use maho_core::source_info::{SourceOrigin, SourceScope};

    let resolved = ResolvedPaths {
        skills: vec![
            ResolvedResource {
                path: "/home/u/.maho/agent/skills/alpha/SKILL.md".to_owned(),
                enabled: true,
                metadata: PathMetadata {
                    source: "auto".to_owned(),
                    scope: SourceScope::User,
                    origin: SourceOrigin::TopLevel,
                    base_dir: Some("/home/u/.maho/agent/skills".to_owned()),
                },
            },
            ResolvedResource {
                path: "/home/u/.maho/agent/skills/beta/SKILL.md".to_owned(),
                enabled: false,
                metadata: PathMetadata {
                    source: "auto".to_owned(),
                    scope: SourceScope::User,
                    origin: SourceOrigin::TopLevel,
                    base_dir: Some("/home/u/.maho/agent/skills".to_owned()),
                },
            },
        ],
        ..ResolvedPaths::default()
    };
    let groups = build_groups(&resolved, "/home/u/.maho/agent", "/home/u", ".maho");
    assert_eq!(groups.len(), 1);
    assert_eq!(groups[0].label, "User (~/.maho/agent/skills/)");
    assert_eq!(groups[0].subgroups.len(), 1);
    let names: Vec<&str> = groups[0].subgroups[0]
        .items
        .iter()
        .map(|item| item.display_name.as_str())
        .collect();
    assert_eq!(names, vec!["alpha", "beta"]);

    let theme = theme();
    let mut scopes = std::collections::BTreeMap::new();
    scopes.insert(ConfigWriteScope::Global, resolved);
    scopes.insert(ConfigWriteScope::Project, ResolvedPaths::default());
    let settings = RecordingSettings::default();
    let mut selector = ConfigSelectorComponent::new(
        &theme,
        scopes,
        Box::new(settings),
        "/home/u/project",
        "/home/u/.maho/agent",
        ".maho",
        Box::new(|| {}),
        Box::new(|| {}),
        Box::new(|| {}),
        Some(30),
        ConfigWriteScope::Global,
        true,
    );
    let rendered = selector.render(120).join("\n");
    assert!(rendered.contains("Global Resources"), "{rendered}");
    assert!(rendered.contains("Skills"), "{rendered}");
    assert!(rendered.contains("alpha"), "{rendered}");
    assert!(rendered.contains("[x]"), "{rendered}");
    assert!(rendered.contains("[ ]"), "{rendered}");

    // Space toggles the first item and records the disable pattern.
    selector.handle_input(" ");
    let list = selector.resource_list();
    let first: ResourceItem = list
        .filtered_items()
        .iter()
        .find_map(|entry| match entry {
            maho_interactive::components::config_selector::FlatEntry::Item(item) => Some(item.clone()),
            _ => None,
        })
        .expect("at least one resource item");
    assert_eq!(first.display_name, "alpha");
    // Selection starts on the first item, not the group header.
    assert!(matches!(
        list.filtered_items()[list.selected_index()],
        maho_interactive::components::config_selector::FlatEntry::Item(_)
    ));

    selector.switch_write_scope();
    let project = selector.render(120).join("\n");
    assert!(project.contains("Project Local Resources"), "{project}");
}

/// A recording ConfigSettingsHost that keeps the arrays the selector writes.
#[derive(Default)]
struct RecordingSettings {
    state: std::cell::RefCell<std::collections::BTreeMap<String, Vec<String>>>,
}

impl maho_interactive::components::config_selector::ConfigSettingsHost for RecordingSettings {
    fn get_global_settings(&self) -> Value {
        let state = self.state.borrow();
        let mut map = serde_json::Map::new();
        for (key, values) in state.iter() {
            map.insert(
                key.clone(),
                Value::Array(values.iter().cloned().map(Value::String).collect()),
            );
        }
        Value::Object(map)
    }

    fn get_project_settings(&self) -> Value {
        self.get_global_settings()
    }

    fn set_packages(&mut self, _packages: &[Value]) {}
    fn set_project_packages(&mut self, _packages: &[Value]) {}

    fn set_extension_paths(&mut self, paths: &[String]) {
        self.state.borrow_mut().insert("extensions".to_owned(), paths.to_vec());
    }
    fn set_project_extension_paths(&mut self, paths: &[String]) {
        self.set_extension_paths(paths);
    }
    fn set_skill_paths(&mut self, paths: &[String]) {
        self.state.borrow_mut().insert("skills".to_owned(), paths.to_vec());
    }
    fn set_project_skill_paths(&mut self, paths: &[String]) {
        self.set_skill_paths(paths);
    }
    fn set_prompt_template_paths(&mut self, paths: &[String]) {
        self.state.borrow_mut().insert("prompts".to_owned(), paths.to_vec());
    }
    fn set_project_prompt_template_paths(&mut self, paths: &[String]) {
        self.set_prompt_template_paths(paths);
    }
    fn set_theme_paths(&mut self, paths: &[String]) {
        self.state.borrow_mut().insert("themes".to_owned(), paths.to_vec());
    }
    fn set_project_theme_paths(&mut self, paths: &[String]) {
        self.set_theme_paths(paths);
    }
}

/// The theme selector preselects the current theme and renders both borders.
#[test]
fn theme_selector_preselects_current_theme() {
    let theme = theme();
    let selected = Rc::new(std::cell::RefCell::new(String::new()));
    let previewed = Rc::new(std::cell::RefCell::new(String::new()));
    let sink = Rc::clone(&selected);
    let preview_sink = Rc::clone(&previewed);
    let mut selector = ThemeSelectorComponent::new(
        &theme,
        "light",
        &["dark".to_owned(), "light".to_owned()],
        Box::new(move |name| *sink.borrow_mut() = name.to_owned()),
        Box::new(|| {}),
        Box::new(move |name| *preview_sink.borrow_mut() = name.to_owned()),
    );
    let rendered = selector.render(60).join("\n");
    assert!(rendered.contains("(current)"), "{rendered}");
    assert!(rendered.contains("light"), "{rendered}");
    selector.handle_input("\r");
    assert_eq!(*selected.borrow(), "light");
}

/// The extension selector windows long lists and reports the picked option.
#[test]
fn extension_selector_windows_and_selects() {
    let theme = theme();
    let options: Vec<String> = (0..20).map(|index| format!("option-{index}")).collect();
    let picked = Rc::new(std::cell::RefCell::new(String::new()));
    let sink = Rc::clone(&picked);
    let mut selector = ExtensionSelectorComponent::new(
        &theme,
        full_keybindings(),
        "Pick",
        options,
        Box::new(move |option| *sink.borrow_mut() = option.to_owned()),
        Box::new(|| {}),
        ExtensionSelectorOptions {
            terminal_rows: Some(20),
            ..ExtensionSelectorOptions::default()
        },
    );
    let rendered = selector.render(60).join("\n");
    assert!(rendered.contains("more below"), "{rendered}");
    assert!(rendered.contains("navigate"), "{rendered}");
    assert!(rendered.contains("Pick"), "{rendered}");
    selector.handle_input("j");
    assert_eq!(selector.selected_index(), 1);
    selector.handle_input("\r");
    assert_eq!(*picked.borrow(), "option-1");
}

/// The extension input prefills by typing, so the cursor lands after the initial value.
#[test]
fn extension_input_prefills_with_cursor_at_end() {
    let theme = theme();
    let submitted = Rc::new(std::cell::RefCell::new(String::new()));
    let sink = Rc::clone(&submitted);
    let mut component = ExtensionInputComponent::new(
        &theme,
        "Name",
        Box::new(move |value| *sink.borrow_mut() = value.to_owned()),
        Box::new(|| {}),
        ExtensionInputOptions {
            initial_value: Some("abc".to_owned()),
            ..ExtensionInputOptions::default()
        },
    );
    assert_eq!(component.input().get_value(), "abc");
    component.handle_input("d");
    assert_eq!(component.input().get_value(), "abcd");
    let rendered = component.render(60).join("\n");
    assert!(rendered.contains("Name"), "{rendered}");
    assert!(rendered.contains("submit"), "{rendered}");
    component.handle_input("\r");
    assert_eq!(*submitted.borrow(), "abcd");
}

/// The OAuth selector labels provider auth types and filters by the search input.
#[test]
fn oauth_selector_labels_and_filters_providers() {
    let theme = theme();
    let providers = vec![
        AuthSelectorProvider {
            id: "anthropic".to_owned(),
            name: "Anthropic".to_owned(),
            auth_type: AuthSelectorAuthType::OAuth,
            method_name: Some("Claude Pro".to_owned()),
            status: None,
        },
        AuthSelectorProvider {
            id: "openai".to_owned(),
            name: "OpenAI".to_owned(),
            auth_type: AuthSelectorAuthType::ApiKey,
            method_name: None,
            status: None,
        },
    ];
    assert_eq!(format_auth_selector_provider_type(AuthSelectorAuthType::OAuth), "subscription");
    assert_eq!(format_auth_selector_provider_type(AuthSelectorAuthType::ApiKey), "API key");

    let picked = Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
    let sink = Rc::clone(&picked);
    let mut selector = OAuthSelectorComponent::new(
        &theme,
        AuthSelectorMode::Login,
        providers,
        Box::new(move |id, auth_type| {
            sink.borrow_mut().push(format!("{id}:{}", format_auth_selector_provider_type(auth_type)))
        }),
        Box::new(|| {}),
        None,
    );
    let rendered = selector.render(80).join("\n");
    assert!(rendered.contains("Select provider to configure:"), "{rendered}");
    assert!(rendered.contains("[subscription]"), "{rendered}");
    assert!(rendered.contains("unconfigured"), "{rendered}");

    for ch in "openai".chars() {
        selector.handle_input(&ch.to_string());
    }
    assert_eq!(selector.filtered_providers().len(), 1);
    assert_eq!(selector.filtered_providers()[0].id, "openai");
    selector.handle_input("\r");
    assert_eq!(*picked.borrow(), vec!["openai:API key".to_owned()]);
}

/// Keybinding hints render the pinned senpi key aliases and capitalization.
#[test]
fn keybinding_hints_format_like_senpi() {
    let golden = golden();
    for case in golden["helpers"]["formatKeyText"].as_array().expect("formatKeyText") {
        let key = case[0].as_str().unwrap_or_default();
        assert_eq!(format_key_text(key, false), case[1].as_str().unwrap_or_default(), "{key}");
        assert_eq!(format_key_text(key, true), case[2].as_str().unwrap_or_default(), "{key}");
    }
    let theme = theme();
    assert_eq!(
        key_hint("tui.select.confirm", "select", &theme),
        format!(
            "{}{}",
            theme.fg(ThemeColor::Dim, "enter"),
            theme.fg(ThemeColor::Muted, " select")
        )
    );
    assert_eq!(
        raw_key_hint("↑↓", "navigate", &theme),
        format!(
            "{}{}",
            theme.fg(ThemeColor::Dim, "↑↓"),
            theme.fg(ThemeColor::Muted, " navigate")
        )
    );
}

/// The auth-type label and the idle-timeout labels match pinned senpi.
#[test]
fn provider_type_and_idle_timeout_labels_match_senpi() {
    let golden = golden();
    for case in golden["helpers"]["formatAuthSelectorProviderType"]
        .as_array()
        .expect("formatAuthSelectorProviderType")
    {
        let auth_type = match case[0].as_str() {
            Some("oauth") => AuthSelectorAuthType::OAuth,
            Some("api_key") => AuthSelectorAuthType::ApiKey,
            other => panic!("unexpected auth type {other:?}"),
        };
        assert_eq!(
            format_auth_selector_provider_type(auth_type),
            case[1].as_str().unwrap_or_default()
        );
    }
    for case in golden["helpers"]["formatHttpIdleTimeoutMs"]
        .as_array()
        .expect("formatHttpIdleTimeoutMs")
    {
        let timeout_ms = case[0].as_u64().expect("timeout ms");
        assert_eq!(format_http_idle_timeout_ms(timeout_ms), case[1].as_str().unwrap_or_default());
    }
}

/// Session ages use senpi's compact units.
#[test]
fn session_dates_use_senpi_units() {
    let now = 1_700_000_000_000;
    assert_eq!(format_session_date(now - 30_000, now), "now");
    assert_eq!(format_session_date(now - 5 * 60_000, now), "5m");
    assert_eq!(format_session_date(now - 3 * 3_600_000, now), "3h");
    assert_eq!(format_session_date(now - 2 * 86_400_000, now), "2d");
    assert_eq!(format_session_date(now - 10 * 86_400_000, now), "1w");
    assert_eq!(format_session_date(now - 60 * 86_400_000, now), "2mo");
    assert_eq!(format_session_date(now - 400 * 86_400_000, now), "1y");
}

fn session(id: &str, path: &str, parent: Option<&str>, modified_ms: i64) -> SessionInfo {
    SessionInfo {
        path: path.to_owned(),
        id: id.to_owned(),
        cwd: "/work".to_owned(),
        name: None,
        parent_session_path: parent.map(str::to_owned),
        modified_ms,
        message_count: 1,
        first_message: format!("message from {id}"),
        all_messages_text: format!("message from {id}"),
    }
}

/// A root with two branches; the first branch has two leaves, so the tree shows
/// a continuation gutter, a non-last connector and a last connector.
fn three_branch_tree() -> Vec<SessionTreeNode> {
    let root = entry("root", None, "user", "root question");
    let mut branch_a = entry("branch-a", Some("root"), "assistant", "assistant: answer a");
    branch_a.children = vec![
        entry("leaf-a", Some("branch-a"), "assistant", "assistant: answer a1"),
        entry("leaf-b", Some("branch-a"), "assistant", "assistant: answer b1"),
    ];
    let branch_c = entry("branch-c", Some("root"), "user", "user: follow up");
    vec![SessionTreeNode {
        entry: root.entry,
        children: vec![branch_a, branch_c],
        label: None,
        label_timestamp: None,
    }]
}

fn entry(id: &str, parent_id: Option<&str>, role: &str, text: &str) -> SessionTreeNode {
    SessionTreeNode {
        entry: serde_json::json!({
            "id": id,
            "parentId": parent_id,
            "type": "message",
            "message": { "role": role, "content": [{ "type": "text", "text": text }] }
        }),
        children: Vec::new(),
        label: None,
        label_timestamp: None,
    }
}
